<?php
$pageTitle='Deadline alerts';
[$scope,$scopeParams]=current_task_access_sql();
$view=(string)($_GET['view']??'all');
$sql="SELECT t.*,p.name AS project_name,u.full_name AS assignee_name, DATEDIFF(t.due_date,CURDATE()) AS days_left FROM tasks t JOIN projects p ON p.id=t.project_id LEFT JOIN users u ON u.id=t.assigned_to WHERE t.due_date IS NOT NULL AND t.status<>'completed' AND t.due_date<=DATE_ADD(CURDATE(),INTERVAL 7 DAY) $scope";
$params=$scopeParams;
if($view==='overdue')$sql.=' AND t.due_date<CURDATE()';elseif($view==='upcoming')$sql.=' AND t.due_date>=CURDATE()';
$sql.=' ORDER BY t.due_date ASC';$st=$pdo->prepare($sql);$st->execute($params);$alerts=$st->fetchAll();
$overdueCount=count(array_filter($alerts,fn($a)=>(int)$a['days_left']<0));
require __DIR__ . '/../inc/header.php';
?>
<div class="page-toolbar"><p class="muted">Tasks due within the next seven days, including overdue work. Alerts are generated from current due dates.</p><span class="status <?= $overdueCount?'status-blocked':'status-completed' ?>"><?= $overdueCount ?> overdue in this view</span></div>
<section class="stat-grid stat-grid-3"><article class="stat-card"><div class="stat-top"><span>Overdue</span><span class="stat-icon icon-red">!</span></div><div class="stat-number"><?php $st=$pdo->prepare("SELECT COUNT(*) FROM tasks t WHERE t.due_date<CURDATE() AND t.status<>'completed' $scope");$st->execute($scopeParams);echo (int)$st->fetchColumn(); ?></div><div class="stat-note">Needs review</div></article><article class="stat-card"><div class="stat-top"><span>Due today</span><span class="stat-icon icon-amber">◷</span></div><div class="stat-number"><?php $st=$pdo->prepare("SELECT COUNT(*) FROM tasks t WHERE t.due_date=CURDATE() AND t.status<>'completed' $scope");$st->execute($scopeParams);echo (int)$st->fetchColumn(); ?></div><div class="stat-note">Deadline is today</div></article><article class="stat-card"><div class="stat-top"><span>Due in 7 days</span><span class="stat-icon icon-blue">↗</span></div><div class="stat-number"><?php $st=$pdo->prepare("SELECT COUNT(*) FROM tasks t WHERE t.due_date BETWEEN DATE_ADD(CURDATE(),INTERVAL 1 DAY) AND DATE_ADD(CURDATE(),INTERVAL 7 DAY) AND t.status<>'completed' $scope");$st->execute($scopeParams);echo (int)$st->fetchColumn(); ?></div><div class="stat-note">Plan next actions early</div></article></section>
<section class="panel"><div class="panel-heading"><div><h3>Deadline watchlist</h3><p>Open the task update page to record progress or explain a delay.</p></div></div><div class="filter-bar"><a class="filter-chip <?= $view==='all'?'selected':'' ?>" href="index.php?page=alerts&view=all">All alerts</a><a class="filter-chip <?= $view==='overdue'?'selected':'' ?>" href="index.php?page=alerts&view=overdue">Overdue</a><a class="filter-chip <?= $view==='upcoming'?'selected':'' ?>" href="index.php?page=alerts&view=upcoming">Upcoming</a></div><?php if(!$alerts): ?><div class="empty-state"><div class="empty-icon">✓</div><h3>No active deadline alerts</h3><p>No unfinished tasks in this date range match this view.</p></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Task / project</th><th>Assigned to</th><th>Due date</th><th>Timing</th><th>Status</th><th>Progress</th><th>Action</th></tr></thead><tbody><?php foreach($alerts as $a): $d=(int)$a['days_left']; ?><tr><td><strong><?= e($a['title']) ?></strong><small class="cell-sub"><?= e($a['project_name']) ?></small></td><td><?= e($a['assignee_name']?:'Unassigned') ?></td><td><?= e(date_label($a['due_date'])) ?></td><td><?php if($d<0): ?><span class="priority priority-urgent"><?= abs($d) ?> day<?= abs($d)===1?'':'s' ?> overdue</span><?php elseif($d===0): ?><span class="priority priority-high">Due today</span><?php else: ?><span class="priority priority-medium">In <?= $d ?> day<?= $d===1?'':'s' ?></span><?php endif; ?></td><td><span class="status status-<?= e($a['status']) ?>"><?= e(status_label($a['status'])) ?></span></td><td><?= (int)$a['progress_percent'] ?>%</td><td><a class="action-link" href="index.php?page=progress&task_id=<?= (int)$a['id'] ?>">Update task</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<div class="alert alert-info"><strong>Prototype notice:</strong> these are in-app deadline alerts based on due dates stored in the database. Email, SMS and push notifications are not configured.</div>
<?php require __DIR__ . '/../inc/footer.php'; ?>
